package dev.industrialtechnology.test;
import java.util.*;
import java.util.function.BiConsumer;
import java.lang.reflect.*;
import java.io.*;
import com.mojang.authlib.GameProfile;
import cpw.mods.fml.common.Loader;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import dev.industrialtechnology.core.*;
import dev.industrialtechnology.wireless.*;
import net.minecraft.block.Block;
import net.minecraft.item.*;
import net.minecraft.init.*;
import net.minecraft.inventory.*;
import net.minecraft.nbt.*;
import net.minecraft.tileentity.*;
import net.minecraft.world.*;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.util.*;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;

/** Exact installed HBM classes and native multiblock fill helpers; never included in a release. */
public final class ReactorIntegration {
    public static final class Player extends FakePlayer {
        public Player(WorldServer world){super(world,new GameProfile(UUID.fromString("fe1f5840-dd50-4ead-83db-bb6c48b56293"),"ReactorOwner"));capabilities.allowEdit=true;capabilities.isCreativeMode=true;}
        @Override public void addChatMessage(net.minecraft.util.IChatComponent ignored){}
    }
    public static final class Deny {
        int x,y,z;Deny(int x,int y,int z){this.x=x;this.y=y;this.z=z;}
        @SubscribeEvent public void deny(PlayerInteractEvent e){if(e.x==x&&e.y==y&&e.z==z)e.setCanceled(true);}
    }
    public static WorldServer world;public static Player player;public static WirelessData data;public static WirelessEndpoint green,blue,rodMonitor,consoleLink;
    public static TileEntity zirnox,rod,console,controlA,controlB,other,automatic;public static TileEntityChest supply;public static int x,z;private static long start;private static double beginLevel;private static boolean motionChecked;
    public static Block block(String name)throws Exception{return(Block)Class.forName("com.hbm.blocks.ModBlocks").getField(name).get(null);}
    public static Item item(String name)throws Exception{return(Item)Class.forName("com.hbm.items.ModItems").getField(name).get(null);}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static void equal(double actual,double expected,String message){check(Math.abs(actual-expected)<.000001,message+": "+actual+" != "+expected);}
    public static TileEntity build(Block block,int bx,int by,int bz)throws Exception{
        world.setBlock(bx,by,bz,block,12,3);
        Class<?> type=block.getClass();Method fill=null;while(type!=null){try{fill=type.getDeclaredMethod("fillSpace",World.class,int.class,int.class,int.class,ForgeDirection.class,int.class);break;}catch(NoSuchMethodException next){type=type.getSuperclass();}}
        if(fill!=null){fill.setAccessible(true);fill.invoke(block,world,bx,by,bz,ForgeDirection.NORTH,0);}
        return world.getTileEntity(bx,by,bz);
    }
    public static WirelessEndpoint link(Item item,int bx,int by,int bz,int side){
        player.setPosition(bx+.5,by+1,bz-2);player.inventory.currentItem=1;player.inventory.setInventorySlotContents(1,new ItemStack(item));item.onItemUseFirst(player.getHeldItem(),player,world,bx,by,bz,side,.5f,.5f,.5f);
        ForgeDirection d=ForgeDirection.getOrientation(side);TileEntity torch=world.getTileEntity(bx+d.offsetX,by+d.offsetY,bz+d.offsetZ);check(torch instanceof TileRedstoneRelay,"real torch missing at "+bx+","+by+","+bz+" support="+world.getBlock(bx,by,bz)+" meta="+world.getBlockMetadata(bx,by,bz)+" space="+world.getBlock(bx+d.offsetX,by+d.offsetY,bz+d.offsetZ));return data.devices.get(((TileRedstoneRelay)torch).endpoint);
    }
    public static NBTTagCompound monitor(WirelessEndpoint e){return HbmReactors.describe(e,e.reactor,true);}
    private static Item rbmkFuel()throws Exception{Class<?> type=Class.forName("com.hbm.items.machine.ItemRBMKRod");for(Object value:Item.itemRegistry)if(type.isInstance(value)&&type.getField("yield").getDouble(value)>0)return(Item)value;throw new AssertionError("No RBMK fuel registered");}
    public static void setup(WorldServer w)throws Exception{
        world=w;data=WirelessData.get(w);x=(w.getSpawnPoint().posX&~15)+352;z=(w.getSpawnPoint().posZ&~15)+352;
        for(int dx=-1;dx<=5;dx++)for(int dz=-1;dz<=2;dz++)w.getChunkFromChunkCoords((x>>4)+dx,(z>>4)+dz);
        player=new Player(w);player.inventory.currentItem=0;player.inventory.setInventorySlotContents(0,new ItemStack(ModRegistry.terminal));WirelessAccess.terminal(player,player.getHeldItem(),true);
        zirnox=build(block("reactor_zirnox"),x,80,z);
        check(zirnox!=null&&zirnox.getClass().getName().endsWith("TileEntityReactorZirnox"),"native ZIRNOX core missing");
        // These are real extra blocks produced by ReactorZirnox.fillSpace, not proxy stand-ins.
        green=link(ModRegistry.greenStick,x-2,81,z,4);blue=link(ModRegistry.blueStick,x-2,83,z,4);
        w.setBlock(x-2,83,z-1,Blocks.chest,0,3);supply=(TileEntityChest)w.getTileEntity(x-2,83,z-1);
        rod=build(block("rbmk_rod"),x+16,80,z);rodMonitor=link(ModRegistry.greenStick,x+16,80,z,5);
        build(block("rbmk_blank"),x+40,80,z);controlA=build(block("rbmk_control"),x+41,80,z);controlB=build(block("rbmk_control"),x+42,80,z);automatic=build(block("rbmk_control_auto"),x+39,80,z);other=build(block("rbmk_control"),x+45,80,z);
        console=build(block("rbmk_console"),x+52,80,z+8);console.getClass().getMethod("setTarget",int.class,int.class,int.class).invoke(console,x+40,80,z);consoleLink=link(ModRegistry.blueStick,x+52,80,z+8,0);
        controlA.getClass().getField("level").setDouble(controlA,.6);controlB.getClass().getField("level").setDouble(controlB,.2);controlA.getClass().getMethod("setTarget",double.class).invoke(controlA,.6);controlB.getClass().getMethod("setTarget",double.class).invoke(controlB,.6);other.getClass().getMethod("setTarget",double.class).invoke(other,.8);
        ItemStack zr=new ItemStack(item("rod_zirnox"),1,1);zr.setTagCompound(new NBTTagCompound());zr.getTagCompound().setInteger("life",50000);zr.getTagCompound().setString("Marker","preserve-real-fuel");((IInventory)zirnox).setInventorySlotContents(0,zr);
        ItemStack last=new ItemStack(item("rod_zirnox"),1,5);last.setTagCompound(new NBTTagCompound());last.getTagCompound().setInteger("life",87500);((IInventory)zirnox).setInventorySlotContents(23,last);
        zirnox.getClass().getField("heat").setInt(zirnox,50000);
        ItemStack br=new ItemStack(rbmkFuel());Class<?> fuel=br.getItem().getClass();double capacity=fuel.getField("yield").getDouble(br.getItem());Class<?> base=Class.forName("com.hbm.items.machine.ItemRBMKRod");base.getMethod("setYield",ItemStack.class,double.class).invoke(null,br,capacity*.525);base.getMethod("setCoreHeat",ItemStack.class,double.class).invoke(null,br,420);base.getMethod("setHullHeat",ItemStack.class,double.class).invoke(null,br,310);((IInventory)rod).setInventorySlotContents(0,br);
        player.inventory.currentItem=0;
    }
    public static void run(WorldServer w,BiConsumer<String,Runnable> test){
        ReactorTransferChecks.run(test);
        if(!Loader.isModLoaded("hbm")){test.accept("Reactor integration fails gracefully with HBM absent",()->check(!HbmReactors.validFuel(new ItemStack(Items.stick)),"non-HBM item accepted as fuel"));return;}
        try{setup(w);}catch(Exception failure){throw new RuntimeException(failure);}
        test.accept("Real assembled ZIRNOX input/output proxy resolves the actual controller and 24-position native layout",()->{HbmReactors.Access a=HbmReactors.access(green);check(a.online()&&a.core==zirnox&&a.layout.positions.size()==24&&a.layout.rows==7,a.status+": "+a.message);check(a.layout.positions.get(0).row==0&&a.layout.positions.get(0).column==0&&a.layout.positions.get(0).x==18,"first native position incorrect");check(a.layout.positions.get(23).slot==23&&a.layout.positions.get(23).row==6,"last native position missing");});
        test.accept("ZIRNOX monitor lists every actual fuel and empty position with metadata and correct depletion",()->{NBTTagList rods=monitor(green).getTagList("Fuels",10);check(rods.tagCount()==24,"missing core positions");equal(rods.getCompoundTagAt(0).getDouble("Depletion"),25,"uranium depletion");equal(rods.getCompoundTagAt(23).getDouble("Depletion"),50,"plutonium depletion");check(rods.getCompoundTagAt(1).getString("State").equals("EMPTY")&&!rods.getCompoundTagAt(1).hasKey("Icon"),"empty position stale");});
        test.accept("ZIRNOX temperature uses the native 20-to-800 Celsius conversion rather than raw heat units",()->equal(monitor(green).getDouble("TemperatureC"),410,"native Celsius"));
        test.accept("RBMK monitor reads real yield depletion separately from core and skin temperatures",()->{NBTTagCompound f=monitor(rodMonitor).getTagList("Fuels",10).getCompoundTagAt(0);equal(f.getDouble("Depletion"),47.5,"fuel depletion");equal(f.getDouble("Remaining"),52.5,"fuel remaining");equal(f.getDouble("CoreHeat"),420,"core Celsius");equal(f.getDouble("HullHeat"),310,"skin Celsius");check(!f.hasKey("CDepletion"),"invented separate C metric");});
        test.accept("Read-only RBMK monitoring never initializes live fuel NBT and removal clears stale data",()->{IInventory inv=(IInventory)rod;ItemStack original=inv.getStackInSlot(0),fresh=new ItemStack(original.getItem());inv.setInventorySlotContents(0,fresh);monitor(rodMonitor);check(!fresh.hasTagCompound(),"monitor mutated HBM fuel getters");inv.setInventorySlotContents(0,null);NBTTagCompound f=monitor(rodMonitor).getTagList("Fuels",10).getCompoundTagAt(0);check(f.getString("State").equals("EMPTY")&&!f.hasKey("Icon")&&!f.hasKey("Depletion")&&data.devices.containsKey(rodMonitor.id),"stale or removed monitoring link");inv.setInventorySlotContents(0,original);});
        test.accept("Native RBMK top fuel access cap can be linked and resolves the same fuel column",()->{try{int h=((Number)Class.forName("com.hbm.tileentity.machine.rbmk.RBMKDials").getMethod("getColumnHeight",World.class).invoke(null,world)).intValue();WirelessEndpoint cap=link(ModRegistry.greenStick,rod.xCoord,rod.yCoord+h,rod.zCoord,1);check(HbmReactors.access(cap).core==rod,"top fuel cap did not resolve");player.inventory.currentItem=0;}catch(Exception e){throw new RuntimeException(e);}});
        test.accept("ZIRNOX Blue ghost assignment preserves the cursor item, rejects nonfuel and saves desired metadata",()->{
            player.inventory.currentItem=0;TerminalContainer c=new TerminalContainer(player);c.action(WirelessCommand.TAB,2,0,"");c.action(WirelessCommand.SELECT,0,0,blue.id.toString());c.action(ReactorTerminal.VIEW,1,0,"");c.action(ReactorTerminal.SLOT,3,0,"");ItemStack desired=((IInventory)zirnox).getStackInSlot(0).copy();player.inventory.setItemStack(desired);c.slotClick(36,0,0,player);check(desired.stackSize==1&&c.reactors.draft.items[3].equals(Item.itemRegistry.getNameForObject(desired.getItem()))&&c.reactors.draft.metadata[3]==1,"ghost consumed or changed metadata");
            player.inventory.setItemStack(new ItemStack(Items.stick));c.slotClick(36,0,0,player);check(c.reactors.draft.metadata[3]==1&&c.reactors.feedback.contains("actual supported"),"invalid fuel replaced ghost");c.action(ReactorTerminal.SUPPLY,2,0,"");c.action(ReactorTerminal.APPLY,0,0,HbmReactors.access(blue).binding);check(blue.reactor.metadata[3]==1&&blue.reactor.enabled[3]&&blue.reactor.supply==2,"assignment not applied");player.inventory.setItemStack(null);
        });
        test.accept("Actual local feeder moves one real partially used fuel rod into its exact assigned native slot without NBT loss",()->{ItemStack input=((IInventory)zirnox).getStackInSlot(0).copy();supply.setInventorySlotContents(0,input.copy());blue.reactor.running=true;blue.reactorNextPoll=Long.MIN_VALUE;ReactorAutomation.poll(data,blue);check(supply.getStackInSlot(0)==null&&ItemStack.areItemStacksEqual(input,((IInventory)zirnox).getStackInSlot(3)),blue.reactorMessage);});
        test.accept("Occupied and wrong-fuel ZIRNOX targets are never overwritten and do not duplicate supply",()->{ItemStack otherFuel=((IInventory)zirnox).getStackInSlot(23).copy();supply.setInventorySlotContents(0,otherFuel.copy());ItemStack original=((IInventory)zirnox).getStackInSlot(3).copy();blue.reactor.metadata[3]=5;blue.reactorNextPoll=Long.MIN_VALUE;ReactorAutomation.poll(data,blue);check(ItemStack.areItemStacksEqual(original,((IInventory)zirnox).getStackInSlot(3))&&ItemStack.areItemStacksEqual(otherFuel,supply.getStackInSlot(0))&&blue.reactorPositions[3].equals("WRONG FUEL"),"occupied rod overwritten");blue.reactor.metadata[3]=1;});
        test.accept("Missing fuel waits and resumed adjacent supply fills the configured position",()->{blue.reactor.items[4]=blue.reactor.items[3];blue.reactor.metadata[4]=1;blue.reactor.enabled[4]=true;supply.setInventorySlotContents(0,null);blue.reactorNextPoll=Long.MIN_VALUE;ReactorAutomation.poll(data,blue);check(blue.reactorPositions[4].equals("WAITING FOR FUEL"),"missing fuel did not pause");supply.setInventorySlotContents(0,((IInventory)zirnox).getStackInSlot(0).copy());blue.reactorNextPoll=Long.MIN_VALUE;ReactorAutomation.poll(data,blue);check(((IInventory)zirnox).getStackInSlot(4)!=null&&supply.getStackInSlot(0)==null,"supply did not resume");});
        test.accept("Reactor feeder honors cancellable source access permissions without consuming fuel",()->{blue.reactor.items[5]=blue.reactor.items[3];blue.reactor.metadata[5]=1;blue.reactor.enabled[5]=true;supply.setInventorySlotContents(0,((IInventory)zirnox).getStackInSlot(0).copy());Deny deny=new Deny(supply.xCoord,supply.yCoord,supply.zCoord);MinecraftForge.EVENT_BUS.register(deny);try{blue.reactorNextPoll=Long.MIN_VALUE;ReactorAutomation.poll(data,blue);check(((IInventory)zirnox).getStackInSlot(5)==null&&supply.getStackInSlot(0)!=null&&blue.reactorMessage.contains("PERMISSION"),"protection bypassed");}finally{MinecraftForge.EVENT_BUS.unregister(deny);}});
        test.accept("Auto fuel supply skips an empty earlier neighbor and chooses extractable fuel for an empty assigned slot",()->{
            int bx=blue.x,by=blue.y,bz=blue.z+1;check(w.isAirBlock(bx,by,bz),"south test chest position occupied");
            ReactorSettings settings=blue.reactor.copy();ItemStack before=((IInventory)zirnox).getStackInSlot(6);ItemStack[] stock=new ItemStack[27];for(int i=0;i<27;i++){ItemStack s=supply.getStackInSlot(i);stock[i]=s==null?null:s.copy();}
            try{w.setBlock(bx,by,bz,Blocks.chest,0,3);TileEntityChest later=(TileEntityChest)w.getTileEntity(bx,by,bz);for(int i=0;i<27;i++)supply.setInventorySlotContents(i,null);ItemStack fuel=((IInventory)zirnox).getStackInSlot(0).copy();later.setInventorySlotContents(0,fuel.copy());blue.reactor=new ReactorSettings();blue.reactor.assign(6,fuel);blue.reactor.enabled[6]=true;blue.reactor.running=true;blue.reactor.supply=-1;blue.reactorNextPoll=Long.MIN_VALUE;
                NBTTagCompound n=monitor(blue);check(n.getInteger("SupplyZ")==bz&&n.getString("SupplyMessage").equals("READY"),"Auto chose an empty inventory");ReactorAutomation.poll(data,blue);check(ItemStack.areItemStacksEqual(fuel,((IInventory)zirnox).getStackInSlot(6))&&later.getStackInSlot(0)==null,"Auto did not supply exact native slot");
                ((IInventory)zirnox).setInventorySlotContents(6,null);later.setInventorySlotContents(0,fuel.copy());blue.reactor.supply=2;blue.reactorNextPoll=Long.MIN_VALUE;ReactorAutomation.poll(data,blue);check(((IInventory)zirnox).getStackInSlot(6)==null&&later.getStackInSlot(0)!=null&&monitor(blue).getString("SupplyMessage").equals("NO MATCHING FUEL"),"explicit direction silently changed sources");
            }finally{blue.reactor=settings;((IInventory)zirnox).setInventorySlotContents(6,before);for(int i=0;i<27;i++)supply.setInventorySlotContents(i,stock[i]);TileEntity extra=w.getTileEntity(bx,by,bz);if(extra instanceof IInventory)for(int i=0;i<((IInventory)extra).getSizeInventory();i++)((IInventory)extra).setInventorySlotContents(i,null);w.setBlockToAir(bx,by,bz);}
        });
        test.accept("RBMK console reports mixed actual insertion and excludes an unrelated nearby reactor",()->{NBTTagCompound n=monitor(consoleLink);check(n.getInteger("RodCount")==2&&n.getInteger("Automatic")==1&&n.getBoolean("Mixed"),n.toString());equal(n.getDouble("AverageInsertion"),60,"insertion average");});
        test.accept("RBMK 0 10 50 90 100 percent insertion commands use reversed native extraction targets and leave actual motion intact",()->{try{for(int value:new int[]{0,10,50,90,100}){double old=controlA.getClass().getField("level").getDouble(controlA);String message=HbmReactors.setInsertion(consoleLink,value,HbmReactors.access(consoleLink).binding);check(message.startsWith("2 / 2"),message);equal(controlA.getClass().getField("targetLevel").getDouble(controlA),1-value/100.0,"native target");equal(controlA.getClass().getField("level").getDouble(controlA),old,"rod instantly moved");}equal(other.getClass().getField("targetLevel").getDouble(other),.8,"unrelated reactor controlled");}catch(Exception e){throw new RuntimeException(e);}});
        test.accept("RBMK protection reports partial success instead of claiming blocked rods changed",()->{Deny deny=new Deny(controlA.xCoord,controlA.yCoord,controlA.zCoord);MinecraftForge.EVENT_BUS.register(deny);try{String message=HbmReactors.setInsertion(consoleLink,30,HbmReactors.access(consoleLink).binding);check(message.startsWith("1 / 2")&&message.contains("1 blocked"),message);equal(controlA.getClass().getField("targetLevel").getDouble(controlA),0,"blocked rod target changed");equal(controlB.getClass().getField("targetLevel").getDouble(controlB),.7,"allowed rod not changed");}catch(Exception e){throw new RuntimeException(e);}finally{MinecraftForge.EVENT_BUS.unregister(deny);}});
        test.accept("Malformed percent and stale controller binding cannot change rod targets",()->{try{double old=controlB.getClass().getField("targetLevel").getDouble(controlB);check(HbmReactors.setInsertion(consoleLink,17,HbmReactors.access(consoleLink).binding).startsWith("Invalid"),"invalid percent accepted");check(HbmReactors.setInsertion(consoleLink,50,"stale").contains("changed"),"stale binding accepted");equal(controlB.getClass().getField("targetLevel").getDouble(controlB),old,"invalid command changed target");}catch(Exception e){throw new RuntimeException(e);}});
        test.accept("RBMK offline anchor does not generate or load target chunks",()->{try{console.getClass().getMethod("setTarget",int.class,int.class,int.class).invoke(console,900000,80,900000);String message=HbmReactors.setInsertion(consoleLink,50,HbmReactors.access(consoleLink).binding);check(message.contains("offline")&&!world.getChunkProvider().chunkExists(900000>>4,900000>>4),"offline anchor loaded or reported success");console.getClass().getMethod("setTarget",int.class,int.class,int.class).invoke(console,x+40,80,z);}catch(Exception e){throw new RuntimeException(e);}});
        test.accept("Foreign terminal cannot select another owner's reactor endpoint",()->{FakePlayer foreign=new FakePlayer(world,new GameProfile(UUID.randomUUID(),"ForeignReactor"));foreign.inventory.currentItem=0;foreign.inventory.setInventorySlotContents(0,new ItemStack(ModRegistry.terminal));WirelessAccess.terminal(foreign,foreign.getHeldItem(),true);TerminalContainer c=new TerminalContainer(foreign);c.action(WirelessCommand.TAB,2,0,"");c.action(WirelessCommand.SELECT,0,0,consoleLink.id.toString());check(c.selected==null,"foreign reactor selected");});
        test.accept("Reactor monitor in another player dimension reports OTHER DIMENSION",()->{player.inventory.currentItem=0;TerminalContainer c=new TerminalContainer(player);c.action(WirelessCommand.TAB,0,0,"");c.action(WirelessCommand.SELECT,0,0,green.id.toString());int previous=player.dimension;player.dimension=-1;try{check(c.reactors.snapshot(green).getString("Status").equals("OTHER_DIMENSION"),"cross-dimension live reactor read");}finally{player.dimension=previous;}});
        test.accept("Saved reactor configuration retains bindings metadata enables and insertion request without storing live percentages",()->{WirelessEndpoint copy=WirelessEndpoint.read(blue.write());check(copy.reactorCore.equals(blue.reactorCore)&&copy.reactor.items[3].equals(blue.reactor.items[3])&&copy.reactor.metadata[3]==1&&copy.reactor.enabled[3]&&copy.reactor.running,"reactor NBT lost settings");check(!blue.write().toString().contains("Depletion"),"live percentage saved as authoritative");});
        HbmReactors.setInsertion(consoleLink,70,HbmReactors.access(consoleLink).binding);blue.reactor.running=false;supply.setInventorySlotContents(0,null);start=w.getTotalWorldTime();
        try{beginLevel=controlA.getClass().getField("level").getDouble(controlA);NBTTagCompound n=new NBTTagCompound();n.setString("Green",green.id.toString());n.setString("Blue",blue.id.toString());n.setString("RBMK",rodMonitor.id.toString());n.setString("Console",consoleLink.id.toString());n.setInteger("X",x);n.setInteger("Z",z);CompressedStreamTools.writeCompressed(n,new FileOutputStream("reactor-fixtures.nbt"));data.markDirty();}catch(Exception e){throw new RuntimeException(e);}
    }
    public static void tick(WorldServer w,BiConsumer<String,Runnable> test){if(consoleLink==null||motionChecked||w.getTotalWorldTime()-start<140)return;motionChecked=true;test.accept("Real native HBM server ticks gradually move both connected manual control rods to requested insertion",()->{try{equal(controlA.getClass().getField("level").getDouble(controlA),.3,"first rod motion");equal(controlB.getClass().getField("level").getDouble(controlB),.3,"second rod motion");check(Math.abs(beginLevel-.3)>.01,"motion test started at target");}catch(Exception e){throw new RuntimeException(e);}});}
    public static void restore(WorldServer w,BiConsumer<String,Runnable> test){if(!Loader.isModLoaded("hbm"))return;test.accept("Actual restart restores ZIRNOX access ports rod assignments NBT and native controller bindings",()->{try{NBTTagCompound n=CompressedStreamTools.readCompressed(new FileInputStream("reactor-fixtures.nbt"));int x=n.getInteger("X"),z=n.getInteger("Z");for(int dx=-1;dx<=5;dx++)for(int dz=-1;dz<=2;dz++)w.getChunkFromChunkCoords((x>>4)+dx,(z>>4)+dz);WirelessData data=WirelessData.get(w);WirelessEndpoint green=data.devices.get(UUID.fromString(n.getString("Green"))),blue=data.devices.get(UUID.fromString(n.getString("Blue"))),controller=data.devices.get(UUID.fromString(n.getString("Console")));check(HbmReactors.access(green).online()&&monitor(green).getTagList("Fuels",10).tagCount()==24,"saved port/controller link unavailable");check(blue.reactor.metadata[3]==1&&blue.reactor.enabled[3]&&!blue.reactor.running&&controller.reactorLastTarget==70,"saved assignments or requested insertion lost");ItemStack moved=((IInventory)HbmReactors.access(blue).core).getStackInSlot(3);check(moved!=null&&moved.getTagCompound().getString("Marker").equals("preserve-real-fuel"),"real fuel NBT lost on restart");}catch(Exception e){throw new RuntimeException(e);}});}
}
